#nullable enable // autogenerated

namespace PVZEngine.Level
{
    public struct ModifiableConveyorPoolEntry : IConveyorPoolEntry
    {
        public ModifiableConveyorPoolEntry(NamespaceID id, int count, int minCount)
        {
            ID = id;
            Count = count;
            MinCount = minCount;
        }
        public ModifiableConveyorPoolEntry(IConveyorPoolEntry other) : this(other.ID, other.Count, other.MinCount) { }


        public NamespaceID ID { get; }

        public int Count { get; set; }

        public int MinCount { get; set; }
    }
}